-- ----------------------------
-- Table structure for caozuo_set
-- ----------------------------
DROP TABLE IF EXISTS `caozuo_set`;
CREATE TABLE `caozuo_set`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `house_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '仓房编号',
  `temperature_max` decimal(5, 2) NOT NULL DEFAULT 40.00 COMMENT '温度报警上限值（℃）',
  `temperature_collect_time` time(0) NOT NULL DEFAULT '08:00:00' COMMENT '温度采集时间（几点采集）',
  `temperature_interval_hours` int(3) NOT NULL DEFAULT 2 COMMENT '温度采集间隔时间（小时）',
  `humidity_max` decimal(5, 2) NOT NULL DEFAULT 85.00 COMMENT '湿度报警上限值（%）',
  `humidity_collect_time` time(0) NOT NULL DEFAULT '08:00:00' COMMENT '湿度采集时间（几点采集）',
  `humidity_interval_hours` int(3) NOT NULL DEFAULT 2 COMMENT '湿度采集间隔时间（小时）',
  `gas_max` int(11) NOT NULL DEFAULT 100 COMMENT '气体浓度报警上限值（ppm）',
  `gas_collect_time` time(0) NOT NULL DEFAULT '08:00:00' COMMENT '气体浓度采集时间（几点采集）',
  `gas_interval_hours` int(3) NOT NULL DEFAULT 2 COMMENT '气体浓度采集间隔时间（小时）',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_house_no`(`house_no`) USING BTREE COMMENT '仓房编号唯一索引'
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓房基础信息设置表' ROW_FORMAT = Dynamic;

